mappings.INQUIRY.response:
body.GetBillResponse.status = "UNPAID" and $type(body.GetBillResponse.amountDue) = "string"
  ? {"outcome": "SUCCESS", "partnerRef": body.GetBillResponse.billNumber,
     "attributes": {"amount": body.GetBillResponse.amountDue, "dueDate": body.GetBillResponse.dueDate,
       "billPeriod": body.GetBillResponse.billPeriod}}
: body.GetBillResponse.status = "PAID"
  ? {"outcome": "FAILED", "code": "A3-02", "message": "Bill already paid"}
: body.fault.`@code` = "Client" and $type(body.fault.detail.code) = "string" and body.fault.detail.code != ""
  ? {"outcome": "FAILED", "code": body.fault.detail.code, "message": body.fault.detail.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.PAY.response:
body.PayBillResponse.status = "PAID" and $type(body.PayBillResponse.receiptNo) = "string" and body.PayBillResponse.receiptNo != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.PayBillResponse.receiptNo}
: body.PayBillResponse.status = "PENDING"
  ? {"outcome": "PENDING", "partnerRef": body.PayBillResponse.receiptNo}
: body.fault.`@code` = "Client" and $type(body.fault.detail.code) = "string" and body.fault.detail.code != ""
  ? {"outcome": "FAILED", "code": body.fault.detail.code, "message": body.fault.detail.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.STATUS_QUERY.response:
body.PaymentStatusResponse.status = "PAID" and $type(body.PaymentStatusResponse.receiptNo) = "string" and body.PaymentStatusResponse.receiptNo != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.PaymentStatusResponse.receiptNo}
: body.PaymentStatusResponse.status = "PENDING"
  ? {"outcome": "PENDING", "partnerRef": body.PaymentStatusResponse.receiptNo}
: body.PaymentStatusResponse.status = "FAILED" and $type(body.PaymentStatusResponse.code) = "string"
  ? {"outcome": "FAILED", "code": body.PaymentStatusResponse.code, "message": body.PaymentStatusResponse.message}
: body.PaymentStatusResponse.status = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND", "code": body.PaymentStatusResponse.code}
: body.fault.`@code` = "Client" and $type(body.fault.detail.code) = "string" and body.fault.detail.code != ""
  ? {"outcome": "FAILED", "code": body.fault.detail.code, "message": body.fault.detail.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.REVERSE.response:
body.ReversePaymentResponse.status = "REVERSED" and $type(body.ReversePaymentResponse.reversalRef) = "string"
  ? {"outcome": "SUCCESS", "partnerRef": body.ReversePaymentResponse.reversalRef}
: body.fault.`@code` = "Client" and $type(body.fault.detail.code) = "string" and body.fault.detail.code != ""
  ? {"outcome": "FAILED", "code": body.fault.detail.code, "message": body.fault.detail.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.CALLBACK.response:
$type(body.transactionId) != "string" or body.transactionId = "" ? {}
: body.status = "PAID" and $type(body.receiptNo) = "string" and body.receiptNo != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.receiptNo, "reference": body.transactionId}
: body.status = "FAILED" and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "partnerRef": body.receiptNo, "reference": body.transactionId,
     "code": body.code, "message": body.message}
: {}
